; EV1527 433 MHz remote frame (OOK, rc-switch protocol 1 timing); one 24-bit code per host word, acknowledged
; Generated by escgen from protocols/ev1527_tx.yaml: edit the table and
; regenerate (python -m escgen), or take this file over by hand.
; Reference: Silvan Chip EV1527 datasheet: 4 clock cycles per bit, sync of 1 high and 31 low, 20-bit ID and 4 data bits
; Reference: rc-switch, protocol 1: T = 350 us, sync 1:31, zero 1:3, one 3:1 (github.com/sui77/rc-switch)
; Every edge is a DRIVE event at an absolute deadline; escert certifies it.

.default CTX, 0
.default CLK_KHZ, 25000                ; core clock in kHz
.equ T, CLK_KHZ * 35 // 100
.default PIN_TX, 0
.equ P_TX, 1 << PIN_TX

.own  PIN_TX, CTX
.entry CTX, main

main:
    ADDT  16                          ; first deadline after the first commit
    EMIT  P_TX, 0, P_TX               ; idle levels
    ADDT  1
packet:
    POP   r1                          ; one word per packet (waits for the host)
    WAITT                             ; the last packet's final phase has ended
    RDTIME r3
    ADDI  r3, 64
    SETT  r3
    EMIT  P_TX, P_TX, P_TX            ; sync
    ADDT  T
    EMIT  P_TX, 0, P_TX
    ADDT  31 * T
    MOV   r0, r1                      ; 24 bits, MSB first, each zero or one
    SHL   r0, 8                       ; the field's first bit to bit 31
    MOVI  r3, 0
bit1:
    SHL   r0, 1                       ; C = the next bit
    JC    one2
    EMIT  P_TX, P_TX, P_TX            ; zero
    ADDT  T
    EMIT  P_TX, 0, P_TX
    ADDT  3 * T
    JMP   next3
one2:
    EMIT  P_TX, P_TX, P_TX            ; one
    ADDT  3 * T
    EMIT  P_TX, 0, P_TX
    ADDT  T
next3:
    ADDI  r3, 1
    CMPI  r3, 24                      ; Z after the last bit
    JNZ   bit1
    EMIT  P_TX, P_TX, P_TX            ; sync
    ADDT  T
    EMIT  P_TX, 0, P_TX
    ADDT  31 * T
    MOVI  r3, 1
    PUSH  r3                          ; packet sent
    JMP   packet
